from typing import Iterable, List

from hourglass.parsing import format_clock
from hourglass.models import Span


def _check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(
            f"step must divide an hour evenly: {step}"
        )


def _snap(value: int, step: int) -> int:
    """Nearest multiple of step, halves going up."""
    return (value + step // 2) // step * step


def _snap_span(span: Span, step: int) -> Span:
    return Span(_snap(span.start, step), _snap(span.end, step))


def _label(span: Span) -> str:
    hours, extra = divmod(span.minutes, 60)
    start = format_clock(span.start)
    end = format_clock(span.end)
    return f"{start}-{end} ({hours}h {extra}m)"


# ---
def round_labels(spans: Iterable[Span], step: int) -> List[str]:
    """Label each span after rounding both ends to step.

    Raises ValueError for a bad step, or when rounding
    collapses a span to nothing.
    """
    _check_step(step)
    snapped = [_snap_span(span, step) for span in spans]
    return [_label(span) for span in snapped]
