cat > tests/test_rounding.py <<'EOF'
import unittest

from hourglass.rounding import round_labels
from hourglass.models import Span


class RoundLabelTests(unittest.TestCase):
    def test_already_on_step(self):
        self.assertEqual(
            round_labels([Span(540, 1035)], 15),
            ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest(self):
        self.assertEqual(
            round_labels([Span(543, 1030)], 15),
            ["09:00-17:10 (8h 10m)"]
        )

    def test_halfway_rounds_up(self):
        self.assertEqual(
            round_labels([Span(0, 67)], 15),
            ["00:00-01:00 (1h 0m)"]
        )

    def test_end_of_day(self):
        self.assertEqual(
            round_labels([Span(1400, 1439)], 30),
            ["23:30-24:00 (0h 30m)"]
        )

    def test_several_spans_keep_order(self):
        labels = round_labels(
            [Span(480, 720), Span(60, 90)], 60
        )
        self.assertEqual(
            labels,
            ["08:00-12:00 (4h 0m)", "01:00-02:00 (1h 0m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 25, 90, 120):
            with self.subTest(step=step):
                with self.assertRaises(ValueError):
                    round_labels([Span(0, 60)], step)

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_labels([Span(61, 64)], 15)


if __name__ == "__main__":
    unittest.main()
